(() => {
  'use strict';
  var q = function (id) { return document.getElementById(id); };
  var stops = [];
  var messageId = null;

  function note(text, bad) {
    q('status').textContent = text;
    q('status').className = bad ? 'status err' : 'status';
  }

  function timeout(ms) {
    return new Promise(function (_, reject) {
      setTimeout(function () { reject(new Error('等待 MVU 超时（' + ms + 'ms）')); }, ms);
    });
  }

  function readState() {
    var data = Mvu.getMvuData({ type: 'message', message_id: messageId });
    var s = data && data.stat_data ? data.stat_data : null;
    if (!s) throw new Error('本楼没有 MVU 快照：请确认已启用「雾港航站·运行脚本」并新建聊天');
    return s;
  }

  function render(s) {
    q('area').textContent = s.世界 && s.世界.区域 != null ? String(s.世界.区域) : '未记录';
    q('weather').textContent = s.世界 && s.世界.天气 != null ? String(s.世界.天气) : '未记录';
    q('phase').textContent = s.世界 && s.世界.时段 != null ? String(s.世界.时段) : '未记录';
    q('task').textContent = s.角色 && s.角色.当前任务 != null ? String(s.角色.当前任务) : '未记录';
    var stamina = Number(s.角色 && s.角色.体力) || 0;
    stamina = Math.max(0, Math.min(100, stamina));
    q('staminaText').textContent = String(Math.round(stamina));
    q('staminaBar').style.width = stamina + '%';
    var box = q('supplies');
    box.textContent = '';
    var goods = s.物资 || {};
    var keys = Object.keys(goods);
    if (!keys.length) {
      var empty = document.createElement('span');
      empty.className = 'chip';
      empty.textContent = '（无记录）';
      box.appendChild(empty);
    } else {
      keys.forEach(function (k) {
        var chip = document.createElement('span');
        chip.className = 'chip';
        chip.textContent = k + '×' + String(goods[k]);
        box.appendChild(chip);
      });
    }
    q('memoInput').value = s.玩家备忘 && s.玩家备忘.最新 != null ? String(s.玩家备忘.最新) : '';
    q('floor').textContent = '第 ' + messageId + ' 楼快照 · 读取成功';
  }

  function refresh() {
    try {
      render(readState());
      note('');
    } catch (error) {
      note('读取失败：' + error.message, true);
    }
  }

  q('saveMemo').addEventListener('click', async function () {
    var btn = this;
    var text = q('memoInput').value.trim();
    if (!text) { note('先写点什么再记入。', true); return; }
    btn.disabled = true;
    try {
      var before = Mvu.getMvuData({ type: 'message', message_id: messageId });
      if (!before || !before.stat_data) throw new Error('本楼没有 MVU 快照，无法写入');
      var cmd = "_.set('玩家备忘.最新', " + JSON.stringify(text) + ");//玩家手记";
      var next = await Mvu.parseMessage(cmd, before);
      Mvu.replaceMvuData(next, { type: 'message', message_id: messageId });
      var context = window.SillyTavern && typeof window.SillyTavern.getContext === 'function'
        ? window.SillyTavern.getContext()
        : null;
      if (!context || typeof context.saveChat !== 'function') {
        throw new Error('宿主缺少 saveChat，无法确认本次写入已保存');
      }
      await context.saveChat();
      var after = Mvu.getMvuData({ type: 'message', message_id: messageId });
      var ok = after && after.stat_data && after.stat_data.玩家备忘 && String(after.stat_data.玩家备忘.最新) === text;
      if (!ok) throw new Error('保存后同楼读回校验未通过');
      render(after.stat_data);
      note('已保存到第 ' + messageId + ' 楼。');
    } catch (error) {
      note('写入失败：' + error.message, true);
    } finally {
      btn.disabled = false;
    }
  });

  function bindEvents() {
    if (typeof eventOn === 'function' && typeof tavern_events === 'object') {
      [tavern_events.MESSAGE_UPDATED, tavern_events.MESSAGE_SWIPED].forEach(function (name) {
        if (!name) return;
        var handle = stops.push(eventOn(name, function (id) {
          if (Number(id) === messageId) refresh();
        }));
        void handle;
      });
    }

    addEventListener('pagehide', function () {
      stops.forEach(function (item) { if (item && item.stop) item.stop(); });
    }, { once: true });
  }

  (async function boot() {
    try {
      if (typeof getCurrentMessageId !== 'function' || typeof getChatMessages !== 'function') {
        throw new Error('当前不是 Tavern Helper 消息 iframe');
      }
      messageId = getCurrentMessageId();
      if (typeof waitGlobalInitialized !== 'function') {
        throw new Error('宿主缺少 waitGlobalInitialized，请升级 Tavern Helper');
      }
      await Promise.race([waitGlobalInitialized('Mvu'), timeout(6000)]);
      bindEvents();
      refresh();
    } catch (error) {
      messageId = null;
      note('面板不可用：' + error.message, true);
    }
  })();
})();
</script>
